function renderItem(item: LayoutItem, data: RenderData, color: string, clipId: string): string {
  switch (item.type) {
    case 'text': return renderText(item, data, clipId)
    case 'metric': return renderMetric(item, data, clipId)
    case 'forecast': return renderForecast(item, data, clipId)
    case 'line': return `<line x1="${item.x}" y1="${item.y}" x2="${item.x + item.width}" y2="${item.y + item.height}" stroke="${color}" stroke-width="1" />`
  }
}

function anchor(item: LayoutItem): string {
  if (item.align === 'center') return 'middle'
  if (item.align === 'right') return 'end'
  return 'start'
}

function textX(item: LayoutItem): number {
  if (item.align === 'center') return item.x + item.width / 2
  if (item.align === 'right') return item.x + item.width
  return item.x
}

function renderText(item: TextItem, data: RenderData, clipId: string): string {
  return `<defs><clipPath id="${clipId}"><rect x="${item.x}" y="${item.y}" width="${item.width}" height="${item.height}" /></clipPath></defs><text x="${textX(item)}" y="${item.y}" width="${item.width}" height="${item.height}" font-size="${item.fontSize ?? 18}" font-weight="${item.weight ?? 400}" text-anchor="${anchor(item)}" clip-path="url(#${clipId})">${interpolate(item.text, data.values)}</text>`
}

function renderMetric(item: MetricItem, data: RenderData, clipId: string): string {
  const defaultFilter = item.valueFormat === 'duration-minutes' ? 'minutes' : item.valueFormat
  const snapshot = data.itemSnapshots?.[item.id]
  const formattedValue = interpolateMetric(item.value, data, defaultFilter, item.unitSource, item.explicitUnitOccurrences, snapshot)
  const valueFontSize = item.fontSize ?? 30
  return `<defs><clipPath id="${clipId}"><rect x="0" y="0" width="${item.width}" height="${item.height}" /></clipPath></defs><g transform="translate(${item.x},${item.y})">
    <rect width="${item.width}" height="${item.height}" rx="10" fill="#f7f7f7" stroke="#111" />
    <g clip-path="url(#${clipId})">
      <text x="16" y="14" font-size="18" class="muted">${escapeXml(item.label)}</text>
      <text x="16" y="46" font-size="${valueFontSize}" font-weight="700" dominant-baseline="alphabetic">${formattedValue}</text>
    </g>
  </g>`
}

function interpolateMetric(template: string, data: RenderData, defaultFilter?: string, unitSource?: string, explicitUnitOccurrences: number[] = [], snapshot?: { source: string; state: string; unit?: string }): string {
  let result = ''
  let lastIndex = 0
  let occurrence = 0
  const explicitOccurrences = new Set(explicitUnitOccurrences)
  for (const match of template.matchAll(/{{\s*([\w.-]+)(?:\s*\|\s*([\w-]+))?\s*}}/g)) {
    const occurrenceIndex = occurrence++
    const key = match[1]
    const filter = match[2] ?? defaultFilter
    const unit = snapshot?.source === key ? snapshot.unit : data.states[key]?.attributes.unit_of_measurement
    result += escapeXml(template.slice(lastIndex, match.index))
    const value = formatValue(snapshot?.source === key ? snapshot.state : data.values[key], filter)
    result += escapeXml(value)
    if (key === unitSource && value !== '—' && typeof unit === 'string' && unit && (!filter || filter === 'raw')
      && !explicitOccurrences.has(occurrenceIndex)
      && !placeholderHasLegacyExplicitMetricUnit(template, match.index, match[0], unit)) result += ` ${escapeXml(unit)}`
    lastIndex = match.index + match[0].length
  }
  return result + escapeXml(template.slice(lastIndex))
}

function legacyMetricUnitLiteral(value: string | undefined, knownUnit: string): boolean {
  if (!value) return false
  if (knownUnit && value === knownUnit) return true
  return /^(?:°[CFK]|%|‰|[$€£¥]|ms|s|sec|secs|min|mins|h|hr|hrs|d|day|days|wk|wks|Hz|kHz|MHz|GHz|V|mV|A|mA|W|kW|Wh|kWh|MWh|VA|J|kJ|Pa|hPa|mmHg|inHg|bar|psi|m|cm|mm|km|ft|yd|mi|mph|g|kg|mg|lb|oz|L|mL|gal|K|C|F|lx|lm|dB|rpm|ppm|ppb|B|KB|MB|GB|TB|µg\/m³|W\/m²)$/u.test(value)
}

function placeholderHasLegacyExplicitMetricUnit(template: string, offset: number, placeholder: string, knownUnit: string): boolean {
  const before = template.slice(Math.max(0, offset - 32), offset).match(/([^\s,.;:!?()[\]{}]+)\s{0,3}$/u)
  const after = template.slice(offset + placeholder.length, offset + placeholder.length + 32).match(/^\s{0,3}([^\s,.;:!?()[\]{}]+)/u)
  return legacyMetricUnitLiteral(before?.[1], knownUnit) || legacyMetricUnitLiteral(after?.[1], knownUnit)
}

function renderForecast(item: ForecastItem, data: RenderData, clipId: string): string {
  const forecast = data.states[item.source]?.attributes.forecast
  const sourceRows = Array.isArray(forecast) ? forecast.slice(0, item.maxItems ?? 8) : []
  const fontSize = item.fontSize ?? 20
  const rowHeight = item.rowHeight ?? Math.max(fontSize + 10, Math.floor(item.height / Math.max(sourceRows.length, 1)))
  const maxVisibleRows = Math.max(Math.floor(item.height / rowHeight), 0)
  const rows = sourceRows.slice(0, maxVisibleRows)
  const hasPrecipitation = rows.some((row) => precipitationValue(row as Record<string, unknown>) !== '')
  const timeX = item.timeX ?? 0
  const tempX = item.tempX ?? 70
  const precipX = item.precipX ?? 112
  const conditionX = item.conditionX ?? (hasPrecipitation ? 168 : 126)
  const conditionWidth = Math.max(item.width - conditionX - 2, 0)
  const conditionFontSize = item.conditionFontSize ?? Math.max(fontSize - 2, 12)
  const rowPaddingY = item.rowPaddingY ?? 3
  const dividerInset = item.dividerInset ?? 0
  const rendered = rows.map((row, index) => {
    const entry = row as Record<string, unknown>
    const y = index * rowHeight
    const time = entry.datetime ? formatTime(entry.datetime) : ''
    const temp = entry.temperature ?? entry.templow ?? '—'
    const condition = String(entry.condition ?? '').replaceAll('-', ' ')
    const precipitation = precipitationValue(entry)
    const conditionText = truncateText(condition, conditionWidth, conditionFontSize)
    const divider = item.rowDivider && index < rows.length - 1
      ? `<line x1="${dividerInset}" y1="${rowHeight - 1}" x2="${item.width - dividerInset}" y2="${rowHeight - 1}" stroke="#111" stroke-width="1" opacity="0.35" />`
      : ''
    return `<g transform="translate(0,${y})">
      <text x="${timeX}" y="${rowPaddingY}" font-size="${fontSize}" font-weight="${item.timeWeight ?? item.weight ?? 700}">${escapeXml(time)}</text>
      <text x="${tempX}" y="${rowPaddingY}" font-size="${fontSize}" font-weight="${item.tempWeight ?? item.weight ?? 700}">${escapeXml(String(temp))}°</text>
      ${hasPrecipitation ? `<text x="${precipX}" y="${rowPaddingY}" font-size="${fontSize}" font-weight="${item.precipWeight ?? 700}" class="muted">${escapeXml(precipitation)}</text>` : ''}
      <text x="${conditionX}" y="${rowPaddingY}" font-size="${conditionFontSize}" font-weight="${item.conditionWeight ?? item.weight ?? 800}" fill="#222">${escapeXml(conditionText)}</text>
      ${divider}
    </g>`
  }).join('\n')
  return `<defs><clipPath id="${clipId}"><rect x="0" y="0" width="${item.width}" height="${item.height}" /></clipPath></defs>
  <g transform="translate(${item.x},${item.y})" clip-path="url(#${clipId})">${rendered}</g>`
}

function precipitationValue(entry: Record<string, unknown>): string {
  const value = entry.precipitation_probability ?? entry.precipitationProbability ?? entry.precipitation
  if (value === undefined || value === null || value === '') return ''
  if (typeof value === 'number') return `${Math.round(value)}%`
  return String(value)
}

function truncateText(text: string, maxWidth: number, fontSize: number): string {
  const maxCharacters = Math.max(Math.floor(maxWidth / (fontSize * 0.55)), 0)
  if (text.length <= maxCharacters) return text
  if (maxCharacters <= 1) return ''
  return `${text.slice(0, maxCharacters - 1)}…`
}
